import{_ as s,o as i,c as r,j as e,a}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse(`{"title":"","description":"Fresh's architecture is designed to make it easy to build fast, scalable, and reliable applications.\\n","frontmatter":{"description":"Fresh's architecture is designed to make it easy to build fast, scalable, and reliable applications.\\n"},"headers":[],"relativePath":"en/1.x/concepts/architecture.md","filePath":"en/1.x/concepts/architecture.md"}`),n={name:"en/1.x/concepts/architecture.md"};function l(o,t,d,c,h,p){return i(),r("div",null,[...t[0]||(t[0]=[e("p",null,"Fresh is designed to make it easy to build fast, scalable, and reliable applications. To do this, it makes opinionated decisions about how one should build web applications. These decisions are backed by strong empirical data gathered from experts in the field. Some examples of these principles are:",-1),e("ul",null,[e("li",null,"Page load times should be reduced to a minimum."),e("li",null,"The work performed on the client should be minimized."),e("li",null,"Errors should have a small blast radius - stuff should gracefully degrade.")],-1),e("p",null,[a("The single biggest architecture decision that Fresh makes is its usage of the "),e("a",{href:"https://www.patterns.dev/posts/islands-architecture/",target:"_blank",rel:"noreferrer"},"islands architecture"),a(" pattern. This means that Fresh applications ship pure HTML to the client by default. Parts of a server-rendered page can then be independently re-hydrated with interactive widgets (islands). This means that the client is only responsible for rendering parts of the page that are interactive enough to warrant the extra effort. Any content that is purely static does not have related client-side JavaScript and is thus very lightweight.")],-1)])])}const f=s(n,[["render",l]]);export{m as __pageData,f as default};
